const __pageData = JSON.parse('{"title":"Week 12 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-12.md","filePath":"solutions/week-12.md"}');
